// alwaysOutputData on "Get Due Checkpoints" guarantees at least one item
// reaches this node even when zero checkpoints are due, but that
// placeholder item's json is `{}` — a real RetentionCheckpointOut record
// always has an `id` field, so filtering on that distinguishes "one real
// checkpoint" from "the empty-response placeholder" reliably.
const realCheckpoints = $input.all().filter((item) => item.json && Object.keys(item.json).length > 0);
return [{ json: { due_checkpoint_count: realCheckpoints.length } }];
